    prompt: "Binary search is a convention plus discipline: choose what the interval means, and make every update shrink it without ever skipping a candidate.\n\n`values` is sorted ascending. Return the index of `target`, or `-1` if it is absent. Use the inclusive `[low, high]` convention.",
    exportName: "find_index",
    scaffolds: { L1: "def find_index(values, target):\n    pass", L2: "def find_index(values, target):\n    pass", L3: "def find_index(values, target):\n    pass", L4: "" },
