    solution: "def count_strong_components(vertex_count, edges):\n    forward = [[] for _ in range(vertex_count)]\n    backward = [[] for _ in range(vertex_count)]\n    for source, target in edges:\n        forward[source].append(target)\n        backward[target].append(source)\n    seen = [False] * vertex_count\n    order = []\n    for start in range(vertex_count):\n        if seen[start]:\n            continue\n        stack = [(start, False)]\n        while stack:\n            vertex, done = stack.pop()\n            if done:\n                order.append(vertex)\n                continue\n            if seen[vertex]:\n                continue\n            seen[vertex] = True\n            stack.append((vertex, True))\n            for neighbour in forward[vertex]:\n                if not seen[neighbour]:\n                    stack.append((neighbour, False))\n    assigned = [False] * vertex_count\n    components = 0\n    for vertex in reversed(order):\n        if assigned[vertex]:\n            continue\n        components += 1\n        stack = [vertex]\n        while stack:\n            current = stack.pop()\n            if assigned[current]:\n                continue\n            assigned[current] = True\n            stack.extend(backward[current])\n    return components",
    language: "python",
