    solution: "def has_eulerian_path(vertex_count, edges):\n    if not edges:\n        return True\n    degree = [0] * vertex_count\n    adjacency = [[] for _ in range(vertex_count)]\n    for left, right in edges:\n        degree[left] += 1\n        degree[right] += 1\n        adjacency[left].append(right)\n        adjacency[right].append(left)\n    start = edges[0][0]\n    seen = set()\n    stack = [start]\n    while stack:\n        vertex = stack.pop()\n        if vertex in seen:\n            continue\n        seen.add(vertex)\n        stack.extend(adjacency[vertex])\n    if any(degree[v] > 0 and v not in seen for v in range(vertex_count)):\n        return False\n    odd = sum(1 for v in range(vertex_count) if degree[v] % 2 == 1)\n    return odd in (0, 2)",
