    difficulty: { concept: 4, implementation: 4, recall: 4 },
    estimatedMinutes: 13,
    prompt: "A mean vector locates the cloud; the covariance matrix sets its spread and tilt. But a covariance matrix must be **symmetric** with non-negative variances — and for 2x2, a non-negative determinant, or it would imply a correlation beyond ±1.\n\nReturn `True` if the 2x2 matrix `M` is a valid covariance matrix.",
    exportName: "is_valid_covariance",
    scaffolds: { L1: "def is_valid_covariance(M):\n    pass", L2: "def is_valid_covariance(M):\n    pass", L3: "def is_valid_covariance(M):\n    pass", L4: "" },
