      { name: "k too small", code: "assert fn(5, 1) == []", hidden: false },
      { name: "every index validates once", code: "folds = fn(7, 3)\nseen = sorted(i for _, v in folds for i in v)\nassert seen == list(range(7))", hidden: false },
      { name: "train and validation never overlap", code: "assert all(not (set(t) & set(v)) for t, v in fn(6, 3))", hidden: true }
