    difficulty: { concept: 5, implementation: 4, recall: 4 },
    estimatedMinutes: 13,
    prompt: "Boosting is **sequential**: each new model targets what the previous ones got wrong. In gradient boosting, each round fits the current **residual** and adds a shrunken correction.\n\nStart from `initial` for every example and apply each round's `corrections` scaled by `learning_rate`. Return the final predictions.\n\nA small learning rate is why boosting needs many rounds but resists overfitting.",
    exportName: "boost_predictions",
    scaffolds: { L1: "def boost_predictions(initial, corrections, learning_rate):\n    pass", L2: "def boost_predictions(initial, corrections, learning_rate):\n    pass", L3: "def boost_predictions(initial, corrections, learning_rate):\n    pass", L4: "" },
